def _list(value) -> list[str]:
    nullish = {"none", "null", "n/a", "æœªæåŠ", "æ— "}
    return list(dict.fromkeys(str(x).strip() for x in (value or [])
                              if str(x).strip() and str(x).strip().lower() not in nullish))


