def normalize_summary(
    summary: str | None,
    scopes: list[str],
    disclosure_status: str,
    accounting_status: str,
    non_application_reason: str | None,
) -> str | None:
    """ç»“æ„åŒ–å¥—æœŸä¼šè®¡ç»“è®ºä¼˜å…ˆäºæ¨¡å‹ç”Ÿæˆçš„è‡ªç„¶è¯­è¨€æ‘˜è¦ã€‚"""
    text = (summary or "").strip()
    if disclosure_status == "æœªæåŠ":
        accounting_text = (
            "ï¼›æœªåº”ç”¨å¥—æœŸä¼šè®¡"
            if accounting_status == "æœªåº”ç”¨"
            else ""
        )
        return f"æŠ¥å‘ŠæœŸæœªå‘ç°è¡ç”Ÿå“ä¸šåŠ¡æŠ«éœ²{accounting_text}ã€‚"
    applied_claims = ("é‡‡ç”¨å¥—æœŸä¼šè®¡", "åº”ç”¨å¥—æœŸä¼šè®¡", "å¥—æœŸä¼šè®¡æ ¸ç®—")
    if accounting_status != "æœªåº”ç”¨" or not any(x in text for x in applied_claims):
        return text[:300] or None
    scope_text = "ã€".join(scopes)
    subject = f"{scope_text}è¡ç”Ÿå“ä¸šåŠ¡" if scope_text else "è¡ç”Ÿå“ä¸šåŠ¡"
    result = f"æŠ¥å‘ŠæœŸæŠ«éœ²{subject}ï¼›æœªåº”ç”¨å¥—æœŸä¼šè®¡ã€‚"
    if non_application_reason:
        result += f"æœªåº”ç”¨åŸå› ï¼š{non_application_reason}ã€‚"
    return result[:300]


def verify_raw_value(value: float, raw: str) -> bool:
    """åªç¡®è®¤æ¨¡å‹è¾“å‡ºæ•°å­—å¯åœ¨åŸæ–‡æ‘˜å½•ç›´æ¥æ‰¾åˆ°ï¼›ä¸åšå•ä½æ¢ç®—æˆ–æ¨å¯¼ã€‚"""
    target = float(value)
    for match in re.finditer(r"[-+]?[0-9][0-9,ï¼Œ]*(?:\.[0-9]+)?", raw or ""):
        try:
            candidate = float(match.group(0).replace(",", "").replace("ï¼Œ", ""))
        except ValueError:
            continue
        tolerance = max(1e-8, abs(target) * 1e-8)
        if abs(candidate - target) <= tolerance:
            return True
        if target < 0 and abs(abs(candidate) - abs(target)) <= tolerance:
            before = (raw or "")[max(0, match.start() - 16):match.start()]
            after = (raw or "")[match.end():min(len(raw or ""), match.end() + 4)]
            parenthesized = (
                before.rstrip().endswith(("(", "ï¼ˆ"))
                and after.lstrip().startswith((")", "ï¼‰"))
            )
            loss_word = any(word in before for word in ("æŸå¤±", "äºæŸ", "å‡å°‘"))
            if parenthesized or loss_word:
                return True
    return False


def zero_literal_matches_unit(unit: str, raw: str) -> bool:
    """é˜²æ­¢æŠŠåŒä¸€è¡Œçš„ 0.00% é”™é…ä¸ºé‡‘é¢ 0ã€‚"""
    matches = list(re.finditer(
        r"(?<![0-9.,])[-+]?0(?:\.0+)?(?![0-9.,])",
        raw or "",
    ))
    if not matches:
        return False
    percentage_matches = [
        match for match in matches
        if (raw or "")[match.end():].lstrip().startswith("%")
    ]
    if unit == "%":
        return bool(percentage_matches)
    return len(percentage_matches) < len(matches)


SCALED_UNITS = {
    "åƒå…ƒ": ("å…ƒ", 1_000),
    "ä¸‡å…ƒ": ("å…ƒ", 10_000),
    "ç™¾ä¸‡å…ƒ": ("å…ƒ", 1_000_000),
    "äº¿å…ƒ": ("å…ƒ", 100_000_000),
    "ä¸‡ç¾å…ƒ": ("ç¾å…ƒ", 10_000),
    "äº¿ç¾å…ƒ": ("ç¾å…ƒ", 100_000_000),
}


def restore_literal_scale(value: float, unit: str | None, raw: str) -> tuple[float, str]:
    """æ¨¡å‹è‹¥æ“…è‡ªæ¢ç®—ä¸ºåŸºç¡€å•ä½ï¼Œåˆ™æ¢å¤åŸæ–‡æ•°å€¼åŠåŸæ–‡å•ä½ã€‚"""
    current_value = float(value)
    current_unit = unit or "å…¶ä»–"
    matches = [
        match for match in re.finditer(
        r"([-+]?[0-9][0-9,]*(?:\.[0-9]+)?)\s*(åƒå…ƒ|ä¸‡å…ƒ|ç™¾ä¸‡å…ƒ|äº¿å…ƒ|ä¸‡ç¾å…ƒ|äº¿ç¾å…ƒ)",
        raw or "",
        )
        if SCALED_UNITS[match.group(2)][0] == current_unit
    ]
    for match in matches:
        literal = float(match.group(1).replace(",", ""))
        literal_unit = match.group(2)
        base_unit, scale = SCALED_UNITS[literal_unit]
        converted = literal * scale
        tolerance = max(1e-8, abs(current_value) * 1e-8)
        if abs(abs(converted) - abs(current_value)) <= tolerance:
            restored = -abs(literal) if current_value < 0 else literal
            return restored, literal_unit
    if len(matches) == 1:
        match = matches[0]
        literal = float(match.group(1).replace(",", ""))
        restored = -abs(literal) if current_value < 0 else literal
        return restored, match.group(2)
    return current_value, current_unit


